import { Wallet } from "lucide-react";

import { PaymentRowActions } from "@/components/payment-row-actions";
import { Badge } from "@/components/ui/badge";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import type { PaymentRecord } from "@/types/payment";
import type { ProductRecord } from "@/types/product";
import type { RegistrationRecord } from "@/types/registration";

const statusVariant: Record<string, "secondary" | "default" | "destructive"> = {
  pending: "secondary",
  approved: "default",
  rejected: "destructive",
};

export function PaymentsTable({
  payments,
  emptyMessage = "No payment requests yet.",
  showActions = false,
  doctors = [],
  products = [],
}: {
  payments: PaymentRecord[];
  emptyMessage?: string;
  showActions?: boolean;
  doctors?: RegistrationRecord[];
  products?: ProductRecord[];
}) {
  if (payments.length === 0) {
    return (
      <div className="flex flex-1 items-center justify-center rounded-xl border border-dashed">
        <div className="flex flex-col items-center gap-2 py-16 text-center">
          <div className="bg-muted flex size-12 items-center justify-center rounded-full">
            <Wallet className="text-muted-foreground size-6" />
          </div>
          <p className="text-muted-foreground text-sm">{emptyMessage}</p>
        </div>
      </div>
    );
  }

  return (
    <div className="overflow-x-auto rounded-xl border">
      <Table>
        <TableHeader>
          <TableRow>
            <TableHead>Doctor</TableHead>
            <TableHead>Product</TableHead>
            <TableHead>Amount</TableHead>
            <TableHead>Requested By</TableHead>
            <TableHead>Status</TableHead>
            <TableHead>Submitted</TableHead>
            {showActions && <TableHead className="text-right">Actions</TableHead>}
          </TableRow>
        </TableHeader>
        <TableBody>
          {payments.map((payment) => (
            <TableRow key={payment._id}>
              <TableCell className="font-medium">
                {payment.doctorName || "-"}
                {payment.doctorId ? (
                  <span className="text-muted-foreground ml-1 font-mono text-xs">
                    ({payment.doctorId})
                  </span>
                ) : null}
              </TableCell>
              <TableCell className="text-muted-foreground">
                {payment.productName || "-"}
              </TableCell>
              <TableCell>₹{payment.amount.toLocaleString("en-IN")}</TableCell>
              <TableCell>{payment.requestedBy?.name ?? "-"}</TableCell>
              <TableCell>
                <Badge variant={statusVariant[payment.status ?? "pending"]}>
                  {payment.status}
                </Badge>
              </TableCell>
              <TableCell className="text-muted-foreground">
                {payment.createdAt
                  ? new Date(payment.createdAt).toLocaleDateString("en-IN", {
                      year: "numeric",
                      month: "short",
                      day: "numeric",
                    })
                  : "-"}
              </TableCell>
              {showActions && (
                <TableCell>
                  <PaymentRowActions
                    payment={payment}
                    doctors={doctors}
                    products={products}
                  />
                </TableCell>
              )}
            </TableRow>
          ))}
        </TableBody>
      </Table>
    </div>
  );
}
